    Bug 2019941 - Correct bitwise logic in nsMsgDatabase::ClearNewList to properly clear New flag from database. r=mkmelin


    This patch fixes a long-standing logical error in `nsMsgDatabase::ClearNewList`
    that prevented the `nsMsgMessageFlags::New` flag from being stripped from
    message headers in the persistent .msf database. This was particularly visible
    in POP3 accounts where filtered messages would retain a 'New' status longer
    than expected.

    Differential Revision: https://phabricator.services.mozilla.com/D285420

diff --git a/mailnews/db/msgdb/src/nsMsgDatabase.cpp b/mailnews/db/msgdb/src/nsMsgDatabase.cpp
index 7ce3f3103b1..8e50ca632fc 100644
--- a/mailnews/db/msgdb/src/nsMsgDatabase.cpp
+++ b/mailnews/db/msgdb/src/nsMsgDatabase.cpp
@@ -2709,11 +2709,11 @@ NS_IMETHODIMP nsMsgDatabase::ClearNewList(bool notify /* = FALSE */) {
         uint32_t flags;
         (void)msgHdr->GetFlags(&flags);

-        if ((flags | nsMsgMessageFlags::New) != flags) {
+        if (flags & nsMsgMessageFlags::New) {
           msgHdr->AndFlags(~nsMsgMessageFlags::New, &flags);
-          NotifyHdrChangeAll(msgHdr, flags | nsMsgMessageFlags::New, flags,
-                             nullptr);
         }
+        NotifyHdrChangeAll(msgHdr, flags | nsMsgMessageFlags::New, flags,
+                           nullptr);
       }
       if (elementIndex == 0) {
         break;
